('page','rooms','Rooms','published','{"heroKicker":"Accommodations","heroTitle":"Rooms For A Simple, Comfortable Stay","heroText":"Compare the listed bed layouts, then confirm live inventory and pricing directly with Sonesta.","sectionKicker":"Choose your space","sectionTitle":"Pick Your Room","sectionDescription":"Practical layouts with the everyday essentials for your Lafayette visit.","featureKicker":"In-room essentials","featureTitle":"Rest Easy. Head Out Refreshed.","sourceNote":"Room categories and photographs are sourced from the supplied property listings. Inventory, layout and accessibility features must be confirmed during booking."}','{"heroKicker":"Accommodations","heroTitle":"Rooms For A Simple, Comfortable Stay","heroText":"Compare the listed bed layouts, then confirm live inventory and pricing directly with Sonesta.","sectionKicker":"Choose your space","sectionTitle":"Pick Your Room","sectionDescription":"Practical layouts with the everyday essentials for your Lafayette visit.","featureKicker":"In-room essentials","featureTitle":"Rest Easy. Head Out Refreshed.","sourceNote":"Room categories and photographs are sourced from the supplied property listings. Inventory, layout and accessibility features must be confirmed during booking."}',2,now()),
('page','amenities','Amenities','published','{"heroKicker":"Comfort and convenience","heroTitle":"The Essentials, Already Included","heroText":"Useful amenities and practical conveniences for a straightforward Lafayette stay.","sectionKicker":"Hotel amenities","sectionTitle":"Comfort Without Complication","sectionDescription":"Call ahead to confirm current breakfast service and seasonal pool availability.","roomKicker":"Inside your room","roomTitle":"Everyday Conveniences Close At Hand","roomText":"Sonesta lists a microwave, mini-fridge, flat-screen cable TV and complimentary Wi-Fi among the in-room conveniences.","roomNote":"Specific features and accessible arrangements can vary by room. Call the hotel before booking when a particular feature is essential."}','{"heroKicker":"Comfort and convenience","heroTitle":"The Essentials, Already Included","heroText":"Useful amenities and practical conveniences for a straightforward Lafayette stay.","sectionKicker":"Hotel amenities","sectionTitle":"Comfort Without Complication","sectionDescription":"Call ahead to confirm current breakfast service and seasonal pool availability.","roomKicker":"Inside your room","roomTitle":"Everyday Conveniences Close At Hand","roomText":"Sonesta lists a microwave, mini-fridge, flat-screen cable TV and complimentary Wi-Fi among the in-room conveniences.","roomNote":"Specific features and accessible arrangements can vary by room. Call the hotel before booking when a particular feature is essential."}',3,now()),
